61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
72	     * new owner's id, its assigned {@code memberId}, its {@code registrationDate} and its
73	     * numeric {@code membershipLevel}.
74	     */
75	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
76	
77	    /**
78	     * Monotonically increasing sequence assigned to each structured {@code OWNER_CREATED} audit event,
79	     * so the immutable event stream carries a strictly increasing {@code seq} across creates.
80	     */
81	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
82	        new java.util.concurrent.atomic.AtomicLong();
83	
84	    /**
85	     * Name of the optional request header carrying an idempotency token for owner creation.
86	     */
87	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
88	
89	    /**
90	     * Idempotency store mapping a previously seen {@code Idempotency-Key} to the id of the owner
91	     * originally created under it. When a create repeats with a key already present here, the
92	     * originally created owner is returned (200 OK) instead of creating a duplicate.
93	     */
94	    private final java.util.Map<String, Integer> idempotencyKeyToOwnerId =
95	        new java.util.concurrent.ConcurrentHashMap<>();
96	
97	    private final ClinicService clinicService;
98	
99	    private final OwnerMapper ownerMapper;
100	
101	    private final PetMapper petMapper;
102	
103	    private final VisitMapper visitMapper;
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        String idempotencyKey = currentIdempotencyKey();
144	        if (idempotencyKey != null) {
145	            Integer existingId = idempotencyKeyToOwnerId.get(idempotencyKey);
146	            if (existingId != null) {
147	                Owner existing = this.clinicService.findOwnerById(existingId);
148	                if (existing != null) {
149	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
150	                }
151	            }
152	        }
153	        HttpHeaders headers = new HttpHeaders();
154	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
155	        applyAddress(owner, ownerFieldsDto);
156	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
157	        rejectFutureRegistrationDate(registrationDate);
158	        if (registrationDate == null) {
159	            registrationDate = java.time.LocalDate.now();
160	        }
161	        registrationDate = toBusinessDay(registrationDate);
162	        owner.setRegistrationDate(registrationDate);
163	        rejectDailyLimitReached(registrationDate);
164	        rejectCityAtCapacity(owner.getCity());
165	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
166	        owner.setTelephone(telephone);
167	        String email = normalizeEmail(ownerFieldsDto.getEmail());
168	        owner.setEmail(email);
169	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
170	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
171	        rejectDuplicateIdentity(owner);
172	        // Joining an existing household is now permitted (an exact-identity duplicate is still
173	        // rejected above); a joiner's membershipLevel is instead capped one above the household's
174	        // current maximum (see cappedMembershipLevel).
175	        String region = Localities.region(owner.getPostcode(), owner.getCity());
176	        owner.setMemberId(assignMemberId(region, owner.getTelephone(), owner.getLastName(), registrationDate));
177	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
178	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
179	        owner.setCapacityWarning(computeCapacityWarning(owner.getCity()));
180	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getPostcode()) + 1);
181	        owner.setMembershipLevel(cappedMembershipLevel(owner));
182	        // A declared household member (sharesHousehold) is created but is not a suspected duplicate.
183	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(owner);
184	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
185	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
186	        this.clinicService.saveOwner(owner);
187	        if (idempotencyKey != null) {
188	            idempotencyKeyToOwnerId.put(idempotencyKey, owner.getId());
189	        }
190	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
191	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
192	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
193	            ownerDto.getMembershipLevel());
194	        AUDIT.info(ownerCreatedEvent(owner, ownerDto));
195	        headers.setLocation(UriComponentsBuilder.newInstance()
196	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
197	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
198	    }
199	
200	    /**
201	     * Builds the immutable structured {@code OWNER_CREATED} audit event emitted (in addition to the
202	     * human-readable audit line) on a successful create, as a JSON object
203	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}. The {@code seq} is
204	     * a fresh value from the monotonically increasing {@link #AUDIT_EVENT_SEQ} sequence, so the event
205	     * stream is strictly ordered across creates.
206	     * <p>
207	     * The {@code memberId} field carries the owner's current primary identifier (see
208	     * {@link #primaryIdentifier}), so the event always names the owner by its live primary identifier.
209	     *
210	     * @param owner the just-saved owner
211	     * @param ownerDto the mapped DTO, used for the (possibly derived) {@code membershipLevel}
212	     * @return the JSON-encoded structured event
213	     */
214	    private String ownerCreatedEvent(Owner owner, OwnerDto ownerDto) {
215	        StringBuilder json = new StringBuilder(128);
216	        json.append('{');
217	        json.append("\"seq\":").append(AUDIT_EVENT_SEQ.incrementAndGet());
218	        json.append(",\"ownerId\":").append(owner.getId());
219	        json.append(",\"memberId\":").append(jsonString(primaryIdentifier(owner)));
220	        json.append(",\"membershipLevel\":").append(ownerDto.getMembershipLevel());
221	        json.append(",\"event\":\"OWNER_CREATED\"");
222	        json.append('}');
223	        return json.toString();
224	    }
225	
226	    /**
227	     * The owner's current primary identifier carried by the structured audit event: the assigned
228	     * {@code memberId}.
229	     *
230	     * @param owner the just-saved owner
231	     * @return the owner's live primary identifier
232	     */
233	    private String primaryIdentifier(Owner owner) {
234	        return owner.getMemberId();
235	    }
236	
237	    /**
238	     * Encodes a value as a JSON string literal (quoted, with the JSON-significant characters escaped),
239	     * or the literal {@code null} when the value is absent.
240	     */
241	    private static String jsonString(String value) {
242	        if (value == null) {
243	            return "null";
244	        }
245	        StringBuilder sb = new StringBuilder(value.length() + 2);
246	        sb.append('"');
247	        for (int i = 0; i < value.length(); i++) {
248	            char c = value.charAt(i);
249	            switch (c) {
250	                case '"' -> sb.append("\\\"");
251	                case '\\' -> sb.append("\\\\");
252	                case '\n' -> sb.append("\\n");
253	                case '\r' -> sb.append("\\r");
254	                case '\t' -> sb.append("\\t");
255	                default -> {
256	                    if (c < 0x20) {
257	                        sb.append(String.format("\\u%04x", (int) c));
258	                    } else {
259	                        sb.append(c);
260	                    }
261	                }
262	            }
263	        }
264	        sb.append('"');
265	        return sb.toString();
266	    }
267	
268	    /**
269	     * Reads the optional {@code Idempotency-Key} header from the current request, if any. A create
270	     * carrying this header is idempotent: the first create under a key is recorded, and a later create
271	     * with the same key returns the originally created owner instead of creating a duplicate.
272	     *
273	     * @return the trimmed idempotency key, or {@code null} when the header is absent, blank or there is
